import{_ as r,C as l,o as t,c as d,a2 as a,b as i,w as n,a as c,E as s,a3 as E}from"./chunks/framework.DToEn73J.js";const f=JSON.parse('{"title":"规划与执行：ReAct vs Plan-and-Execute","description":"","frontmatter":{"title":"规划与执行：ReAct vs Plan-and-Execute","chapter":"4.1","order":1,"summary":"对比走一步看一步的 ReAct 与先规划后执行的 Plan-and-Execute，并给出混合模式（固定计划 + 动态重规划）的工程实现。"},"headers":[],"relativePath":"04-planning-execution/plan-and-execute.md","filePath":"04-planning-execution/plan-and-execute.md","lastUpdated":1787724133000}'),p={name:"04-planning-execution/plan-and-execute.md"};function h(u,e,A,g,x,m){const o=l("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a('<h1 id="规划与执行-react-vs-plan-and-execute" tabindex="-1">规划与执行：ReAct vs Plan-and-Execute <a class="header-anchor" href="#规划与执行-react-vs-plan-and-execute" aria-label="Permalink to &quot;规划与执行：ReAct vs Plan-and-Execute&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>规划与执行解决 Agent 在长程任务中如何分配「何时思考、何时行动」的问题。ReAct 将推理与动作交错在 Agent Loop 中；Plan-and-Execute 则把任务先一次性分解为有序子目标，再逐条执行。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p>两种范式的核心差异在「规划发生的时机」与「上下文占用」：</p><table tabindex="0"><thead><tr><th>维度</th><th>ReAct</th><th>Plan-and-Execute</th></tr></thead><tbody><tr><td>规划时机</td><td>每步实时推理</td><td>执行前一次性规划</td></tr><tr><td>长程任务稳定性</td><td>易偏离、累积误差</td><td>目标明确、可控</td></tr><tr><td>Context Window 占用</td><td>高（思维链随步增长）</td><td>低（计划与执行分离）</td></tr><tr><td>动态环境适应</td><td>强（可随时改路）</td><td>弱（计划固化）</td></tr><tr><td>适用任务</td><td>探索式、交互式检索</td><td>可分解、目标固定的工程任务</td></tr></tbody></table><p><strong>混合模式（推荐）</strong>：先由 Planner 生成结构化计划，Executor 按步执行；当某步失败或环境变化触发重规划。</p>',7)),(t(),i(E,null,{default:n(()=>[s(o,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E7%94%A8%E6%88%B7%E8%BE%93%E5%85%A5%5D%20--%3E%20B%5BPlanner%20%E7%94%9F%E6%88%90%E8%AE%A1%E5%88%92%5D%0A%20%20%20%20B%20--%3E%20C%7B%E8%AE%A1%E5%88%92%E6%9C%89%E6%95%88%3F%7D%0A%20%20%20%20C%20--%3E%7C%E5%90%A6%7C%20B%0A%20%20%20%20C%20--%3E%7C%E6%98%AF%7C%20D%5B%E6%89%A7%E8%A1%8C%E6%AD%A5%E9%AA%A4%20i%5D%0A%20%20%20%20D%20--%3E%20E%7B%E6%88%90%E5%8A%9F%3F%7D%0A%20%20%20%20E%20--%3E%7C%E6%98%AF%7C%20F%7B%E8%BF%98%E6%9C%89%E6%AD%A5%E9%AA%A4%3F%7D%0A%20%20%20%20E%20--%3E%7C%E5%90%A6%7C%20G%5BReplan%20%E9%87%8D%E8%A7%84%E5%88%92%5D%0A%20%20%20%20G%20--%3E%20D%0A%20%20%20%20F%20--%3E%7C%E6%98%AF%7C%20D%0A%20%20%20%20F%20--%3E%7C%E5%90%A6%7C%20H%5B%E8%BF%94%E5%9B%9E%E7%BB%93%E6%9E%9C%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>最小实现：Planner 输出 <code>Plan{steps: Step[]}</code>，Executor 循环取 <code>steps[i]</code> 调 Tool，把 <code>observation</code> 回写步骤状态；失败则带最近 K 步轨迹重新调用 Planner。</p><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>纯 ReAct 在超过 10 步的任务上漂移明显——模型在长链中忘记初始目标，且 Context Window 被历史占用迫使截断。纯 Plan-and-Execute 在状态高度不确定的环境（如网页操作）中会因计划失真而整体失败。混合模式用「稳定骨架 + 局部自适应」换取两者的优点。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>把计划写得太细（原子级），导致重规划成本高、僵化；计划应到「可验证子目标」粒度。</li><li>Planner 与 Executor 共用同一上下文，重规划时未隔离历史，引发 Prompt Injection 式污染。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li><strong>LangGraph</strong>：用 <code>Plan-and-Execute</code> 官方示例，<code>planner</code> 与 <code>executor</code> 为独立节点（<a href="https://langchain-ai.github.io/langgraph/tutorials/plan-and-execute/%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://langchain-ai.github.io/langgraph/tutorials/plan-and-execute/）。</a></li><li><strong>Claude Agent SDK</strong>：支持 <code>TodoWrite</code> 式显式规划，配合 Agent Loop 动态执行（<a href="https://docs.anthropic.com/en/docs/claude-agent-sdk%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/claude-agent-sdk）。</a></li><li><strong>OpenAI Agents SDK</strong>：Handoff 可在子 Agent 间做计划拆分（<a href="https://openai.github.io/openai-agents-python/%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/）。</a></li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/04-planning-execution/todo-management">/04-planning-execution/todo-management</a></li><li><a href="/fk-ai-agent/04-planning-execution/error-recovery">/04-planning-execution/error-recovery</a></li><li><a href="/fk-ai-agent/01-agent-basics/agent-loop">/01-agent-basics/agent-loop</a></li><li><a href="/fk-ai-agent/02-capability-extension/multi-agent">/02-capability-extension/multi-agent</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',11))])}const b=r(p,[["render",h]]);export{f as __pageData,b as default};
